// Evaluate an integer arithmetic expression and return its value, or None
// if the expression is invalid.
// Tokens are non-negative decimal integer literals (one or more ASCII digits),
// the operators + - * / % ^ and the parentheses ( ). Space characters (" ")
// may appear between tokens and are ignored; any other character, tabs
// included, makes the expression invalid.
// Precedence, from lowest to highest:
//   1. binary + and -, left-associative;
//   2. binary *, / and %, left-associative;
//   3. prefix unary minus, which may repeat ("--3" is 3);
//   4. ^ (power), right-associative ("2^3^2" is 2^9); it binds tighter than a
//      unary minus on its left ("-2^2" is -4), and its right operand may start
//      with unary minus ("2^-1" parses, then fails as a negative exponent);
//   5. integer literals and parenthesized expressions.
// / truncates toward zero and % takes the sign of the dividend, as in C
// ("-7 / 2" is -3 and "-7 % 2" is -1). 0^0 is 1.
// Return None for an empty or all-space expression, any syntax error (a missing
// operand, two adjacent numbers such as "1 2", empty or unbalanced
// parentheses), division or remainder by zero, and a negative exponent.
// Every value in the tests fits in a signed 64-bit integer.
// Examples:
//   eval_arith("2 + 3 * (4 - 1)") == Some(11)
//   eval_arith("2 ^ 3 ^ 2") == Some(512)
fn eval_arith(expr: Str) -> Option[Int] {
  let toks = tokenize(expr)?;
  let (v, p) = parse_sum(toks, 0)?;
  if p == len(toks) { Some(v) } else { None }
}

type Tok = Num(v: Int) | Sym(s: Str)

fn tokenize(s: Str) -> Option[List[Tok]] {
  let cs = chars(s);
  let n = len(cs);
  let mut toks: List[Tok] = [];
  let mut i = 0;
  while i < n {
    let c = cs[i];
    if c == " " {
      i = i + 1;
    } else if is_digit(c) {
      let mut j = i;
      while j < n && is_digit(cs[j]) {
        j = j + 1;
      }
      toks = push(toks, Num(parse_int(join(slice(cs, i, j), ""))?));
      i = j;
    } else if str_contains("+-*/%^()", c) {
      toks = push(toks, Sym(c));
      i = i + 1;
    } else {
      return None;
    }
  }
  Some(toks)
}

fn sym_at(toks: List[Tok], p: Int) -> Str {
  match get(toks, p) {
    Some(Sym(s)) => s,
    _ => "",
  }
}

fn parse_sum(toks: List[Tok], p0: Int) -> Option[(Int, Int)] {
  let (first, p1) = parse_product(toks, p0)?;
  let mut v = first;
  let mut p = p1;
  while sym_at(toks, p) == "+" || sym_at(toks, p) == "-" {
    let op = sym_at(toks, p);
    let (r, q) = parse_product(toks, p + 1)?;
    v = if op == "+" { v + r } else { v - r };
    p = q;
  }
  Some((v, p))
}

fn parse_product(toks: List[Tok], p0: Int) -> Option[(Int, Int)] {
  let (first, p1) = parse_unary(toks, p0)?;
  let mut v = first;
  let mut p = p1;
  while sym_at(toks, p) == "*" || sym_at(toks, p) == "/" || sym_at(toks, p) == "%" {
    let op = sym_at(toks, p);
    let (r, q) = parse_unary(toks, p + 1)?;
    if op != "*" && r == 0 {
      return None;
    }
    v = if op == "*" { v * r } else if op == "/" { v / r } else { v % r };
    p = q;
  }
  Some((v, p))
}

fn parse_unary(toks: List[Tok], p: Int) -> Option[(Int, Int)] {
  if sym_at(toks, p) == "-" {
    let (v, q) = parse_unary(toks, p + 1)?;
    Some((-v, q))
  } else {
    parse_power(toks, p)
  }
}

fn parse_power(toks: List[Tok], p: Int) -> Option[(Int, Int)] {
  let (b, q) = parse_atom(toks, p)?;
  if sym_at(toks, q) != "^" {
    return Some((b, q));
  }
  let (e, r) = parse_unary(toks, q + 1)?;
  if e < 0 { None } else { Some((pow(b, e), r)) }
}

fn parse_atom(toks: List[Tok], p: Int) -> Option[(Int, Int)] {
  match get(toks, p) {
    Some(Num(v)) => Some((v, p + 1)),
    Some(Sym("(")) => {
      let (v, q) = parse_sum(toks, p + 1)?;
      if sym_at(toks, q) == ")" { Some((v, q + 1)) } else { None }
    },
    _ => None,
  }
}
